<script setup lang="ts">
import {setFeatureEnabled,bindNavigationCategory} from '@/domain/feature-navigation';import {applyReferenceLayout} from '@/domain/reference-layout';import {normalizeTheme} from '@/domain/normalize-theme';import {computed,ref,watch} from 'vue';import EditorPanel from './EditorPanel.vue';import type {Theme,Section,Category,AppPage,NavItem,Ad} from '@/domain/types';import Choice from './EditorChoice.vue';import CmsCategoryBinding from './CmsCategoryBinding.vue';import {carouselStyles,sectionStyles,pageNames} from '@/domain/presentation';import {api,chooseLocalFile,assetUrl} from '@/services/api';
const props=defineProps<{theme:Theme;active:string;selected:string;page:AppPage;categories:Category[]}>();const emit=defineEmits<{select:[id:string];page:[page:AppPage];message:[value:string];startup:[];announcement:[];update:[]}>();watch(()=>props.theme,normalizeTheme,{immediate:true});const theme=computed(()=>props.theme),selection=ref(props.selected),uploading=ref(false);watch(()=>props.selected,id=>selection.value=id);const section=computed(()=>theme.value.sections.find(s=>s.id===selection.value));const pageSections=computed(()=>theme.value.sections.filter(s=>(s.page||'home')===props.page));const pages=Object.entries(pageNames).map(([id,label])=>({id,label}));const carouselOptions=carouselStyles.map(([id,label])=>({id,label})),moduleOptions=sectionStyles.map(([id,label])=>({id,label}));const id=(prefix:string)=>prefix+'-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,6);const bool=(e:any)=>!!e.detail.value;function setRows(e:any){if(section.value)section.value.limit=Math.min(60,Math.max(1,Number(e.detail.value)||1)*section.value.columns);}
function addSection(){if(theme.value.sections.length>=40)return emit('message','每套模板最多40个模块。');const s:Section={id:id('module'),title:'我的精选',subtitle:'',page:props.page,style:'grid3',kind:'poster',source:'latest',categoryId:'',limit:6,columns:3,enabled:true,orderBy:'latest',radius:4,gap:8,ratio:'2/3',showScore:true,showTitle:true,showNote:true,showYear:false,showMore:true};theme.value.sections.push(s);selection.value=s.id;sectionSignal.value++;moduleSignal.value++;emit('select',s.id);}
function move<T extends {id:string}>(list:T[],row:T,dir:number){const i=list.findIndex(s=>s.id===row.id),target=i+dir;if(target>=0&&target<list.length)[list[i],list[target]]=[list[target],list[i]];}
function moveSection(row:Section,dir:number){const same=theme.value.sections.filter(s=>(s.page||'home')===(row.page||'home'));const index=same.findIndex(s=>s.id===row.id),other=same[index+dir];if(!other)return;const a=theme.value.sections.indexOf(row),b=theme.value.sections.indexOf(other);[theme.value.sections[a],theme.value.sections[b]]=[theme.value.sections[b],theme.value.sections[a]];}
function setSectionStyle(style:string){if(!section.value)return;section.value.style=style as Section['style'];if(style==='grid2')section.value.columns=2;if(style==='grid3')section.value.columns=3;}
function remove<T extends {id:string}>(list:T[],row:T){list.splice(list.findIndex(v=>v.id===row.id),1);}
async function upload(target:any,key:string,accept='.png,.jpg,.jpeg,.webp'){uploading.value=true;try{const f=await chooseLocalFile(accept);target[key]=(await api.asset(f.name,f.data)).url;emit('message','素材已上传至外部运行目录，保存并发布模板后生效。');}catch(e){emit('message',(e as Error).message);}finally{uploading.value=false;}}
function addNav(list:NavItem[],category=false){if(list.length>=20)return;list.push({id:id(category?'category':'nav'),label:category?'新分类':'新导航',page:category?'category':'home',categoryId:'',enabled:true,icon:'◇',activeIcon:'◆'});}
function addSlide(){if(theme.value.carousel.slides.length>=20)return;theme.value.carousel.slides.push({id:id('slide'),title:'新轮播',image:'',video:'',vodId:'',page:'home'});}
function addAd(){if(theme.value.ads.length>=20)return;theme.value.ads.push({id:id('ad'),name:'新广告',slot:'home',enabled:false,media:'image',asset:'',url:'',page:'home',start:'',end:'',duration:5,skipAfter:3,frequency:'session'});}
const sectionSignal=ref(0),moduleSignal=ref(0);watch(()=>props.selected,()=>{sectionSignal.value++;});function editSection(s:Section){selection.value=s.id;sectionSignal.value++;emit('select',s.id);}
const rowCount=computed(()=>section.value?Math.ceil(section.value.limit/section.value.columns):0);
function bindSectionCategory(categoryId:string){if(!section.value)return;section.value.categoryId=categoryId;section.value.source=categoryId?'category':'latest';}
function bindNavCategory(nav:NavItem,categoryId:string){bindNavigationCategory(nav,categoryId);}
</script>
<template><view class="theme-editor">
<template v-if="active==='brand'"><EditorPanel  title="品牌标识"><label>App 名称<input v-model="theme.brand.name" maxlength="24"/></label><label>品牌短句<input v-model="theme.brand.tagline" maxlength="100"/></label><label>品牌 Logo<input v-model="theme.brand.logo" placeholder="图片地址，或上传素材"/></label><image v-if="theme.brand.logo" class="asset-preview" :src="assetUrl(theme.brand.logo)" mode="aspectFit"/><button :disabled="uploading" @click="upload(theme.brand,'logo')">上传 Logo</button><text class="hint">品牌修改同步到当前模板的客户端名称和界面标识。</text></EditorPanel><EditorPanel title="App 开机页面" summary="背景、展示时长与开机预览"><view class="toggle"><text>启用品牌开机页</text><switch :checked="theme.startup.enabled" @change="theme.startup.enabled=bool($event)"/></view><text class="hint">名称、Logo 和品牌短句使用当前骨架的品牌标识。进入首页前展示，之后进入开屏广告。</text><label>展示时长（1–8 秒）<input v-model.number="theme.startup.duration" type="number"/></label><label>背景颜色<input v-model="theme.startup.background" maxlength="7"/></label><label>背景图片<input v-model="theme.startup.image" placeholder="留空使用纯色背景"/></label><button :disabled="uploading" @click="upload(theme.startup,'image')">上传开机背景</button><view class="toggle"><text>显示品牌短句</text><switch :checked="theme.startup.showTagline" @change="theme.startup.showTagline=bool($event)"/></view><button @click="emit('startup')">预览开机页面</button></EditorPanel></template>
<template v-else-if="active==='settings'"><EditorPanel title="免责与隐私" :initial-open="false"><label>免责声明<textarea v-model="theme.clientSettings.disclaimer" maxlength="12000" placeholder="填写实际服务的免责声明"/></label><label>隐私政策<textarea v-model="theme.clientSettings.privacy" maxlength="12000" placeholder="填写实际隐私政策"/></label><label>关于应用<textarea v-model="theme.clientSettings.about" maxlength="4000"/></label></EditorPanel><EditorPanel title="版本推送与更新" summary="发布版本、更新说明和强制更新"><view class="toggle"><text>启动时提示更新</text><switch :checked="theme.clientSettings.notifyOnLaunch" @change="theme.clientSettings.notifyOnLaunch=bool($event)"/></view><view class="toggle"><text>强制更新</text><switch :checked="theme.clientSettings.forceUpdate" @change="theme.clientSettings.forceUpdate=bool($event)"/></view><label>最新版本号<input v-model="theme.clientSettings.latestVersion" placeholder="例如 1.0.1"/></label><label>更新说明<textarea v-model="theme.clientSettings.updateNotes" maxlength="4000"/></label><label>Android 更新下载地址<input v-model="theme.clientSettings.androidUrl" placeholder="https://…"/></label><label>iOS App Store 地址<input v-model="theme.clientSettings.iosUrl" placeholder="https://apps.apple.com/…"/></label><text class="hint">保存并发布后，在线客户端同步版本信息；开启强制更新时，低于最新版本的 App 必须更新后才能继续。</text><button @click="emit('update')">预览更新弹窗</button></EditorPanel></template>
<template v-else-if="active==='layout'"><EditorPanel  title="编辑页面"><Choice :model-value="page" :options="pages" @update:model-value="emit('page',$event)"/><text class="hint">每个页面的模块独立保存，选中哪个模板就编辑哪个模板。</text></EditorPanel>
<EditorPanel v-if="page==='home'" title="轮播图"><Choice v-model="theme.carousel.style" :options="carouselOptions"/><view class="row"><label>高度 px<input type="number" v-model.number="theme.carousel.height"/></label><label>圆角 px<input type="number" v-model.number="theme.carousel.radius"/></label><label>外边距 px<input type="number" v-model.number="theme.carousel.margin"/></label></view><label>图片裁切<Choice v-model="theme.carousel.fit" :options="[{id:'cover',label:'铺满裁切'},{id:'contain',label:'完整显示'}]"/></label><label>标题位置<Choice v-model="theme.carousel.titlePosition" :options="[{id:'bottom',label:'底部'},{id:'side',label:'侧边'},{id:'hidden',label:'隐藏'}]"/></label><label>指示器<Choice v-model="theme.carousel.indicator" :options="[{id:'dots',label:'圆点'},{id:'numbers',label:'数字'},{id:'none',label:'隐藏'}]"/></label><label>切换效果<Choice v-model="theme.carousel.effect" :options="[{id:'slide',label:'滑动'},{id:'fade',label:'淡入'}]"/></label><view class="toggle"><text>自动播放</text><switch :checked="theme.carousel.autoplay" @change="theme.carousel.autoplay=bool($event)"/></view><label>间隔 秒<input type="number" v-model.number="theme.carousel.interval"/></label><view class="toggle"><text>视频静音</text><switch :checked="theme.carousel.muted" @change="theme.carousel.muted=bool($event)"/></view><EditorPanel v-for="s in theme.carousel.slides" :key="s.id" :title="s.title"><template #actions><view class="item-head"><text @click="move(theme.carousel.slides,s,-1)">↑</text><text @click="move(theme.carousel.slides,s,1)">↓</text><text @click="remove(theme.carousel.slides,s)">移除</text></view></template><label>标题<input v-model="s.title"/></label><label>图片地址<input v-model="s.image"/></label><button :disabled="uploading" @click="upload(s,'image')">上传轮播图</button><label v-if="theme.carousel.style==='video'">视频地址<input v-model="s.video" placeholder="HTTPS 视频或上传 MP4"/></label><button v-if="theme.carousel.style==='video'" :disabled="uploading" @click="upload(s,'video','.mp4')">上传视频</button><label>点击绑定影片 ID<input v-model="s.vodId" placeholder="留空时跳转下方页面"/></label><Choice v-model="s.page" :options="pages"/></EditorPanel><button @click="addSlide">＋ 添加轮播图</button><text class="hint">未单独设置轮播图时使用片库前五部影片。</text></EditorPanel>
<EditorPanel  :auto-open="moduleSignal" title="页面内容模块"><template #actions><view class="item-head"><button @click="addSection">＋ 添加</button></view></template><view class="module-row" v-for="s in pageSections" :key="s.id" :class="{selected:selection===s.id}" @click="editSection(s)"><text>{{s.enabled?'●':'○'}} {{s.title}}</text><text>编辑</text><text @click.stop="moveSection(s,-1)">↑</text><text @click.stop="moveSection(s,1)">↓</text><text @click.stop="remove(theme.sections,s)">×</text></view><text class="hint" v-if="!pageSections.length">此页面尚无自定义模块。可以添加多组电影、电视剧、综艺、动漫。</text></EditorPanel>
<EditorPanel v-if="section" :auto-open="sectionSignal" :title="section.title+' · 模块设置'"><view class="toggle"><text>显示模块</text><switch :checked="section.enabled" @change="section.enabled=bool($event)"/></view><label>标题<input v-model="section.title" maxlength="60"/></label><label>副标题<input v-model="section.subtitle" maxlength="120"/></label><label>所属页面<Choice v-model="section.page" :options="pages"/></label><label>模块样式<Choice :model-value="section.style" :options="moduleOptions" @update:model-value="setSectionStyle"/></label><label>绑定 CMS 分类<CmsCategoryBinding :model-value="section.categoryId" :categories="props.categories" @update:model-value="bindSectionCategory"/></label><label>影片排序<Choice v-model="section.orderBy" :options="[{id:'latest',label:'CMS 返回顺序 / 最新'},{id:'score',label:'评分优先'},{id:'manual',label:'手动指定影片 ID'}]"/></label><label v-if="section.orderBy==='manual'">影片 ID 顺序<input v-model="section.manualIds" placeholder="1,2,3"/></label><view class="row"><label>影片数量 1–60<input v-model.number="section.limit" type="number"/></label><label>每行列数 1–6<input v-model.number="section.columns" type="number"/></label><label>组数 / 行数<input :value="rowCount" type="number" @input="setRows"/></label></view><view class="row"><label>圆角 px<input v-model.number="section.radius" type="number"/></label><label>间距 px<input v-model.number="section.gap" type="number"/></label></view><label>海报比例<Choice v-model="section.ratio" :options="[{id:'2/3',label:'竖版 2:3'},{id:'16/9',label:'横版 16:9'},{id:'1/1',label:'方形 1:1'}]"/></label><view class="toggle" v-for="k in [{id:'showTitle',name:'片名'},{id:'showScore',name:'评分'},{id:'showNote',name:'更新标记'},{id:'showYear',name:'年份'},{id:'showMore',name:'更多入口'}]" :key="k.id"><text>{{k.name}}</text><switch :checked="section[k.id as keyof Section]!==false" @change="(section as any)[k.id]=bool($event)"/></view></EditorPanel>

<EditorPanel v-if="page==='schedule'" title="排期内容"><EditorPanel v-for="r in theme.schedule" :key="r.id" :title="r.title"><label>片名<input v-model="r.title"/></label><label>日期<input v-model="r.date" placeholder="2026-10-10"/></label><label>影片 ID<input v-model="r.vodId"/></label><button @click="remove(theme.schedule,r)">移除</button></EditorPanel><button @click="theme.schedule.push({id:id('schedule'),title:'新排期',date:new Date().toISOString().slice(0,10),vodId:''})">＋ 添加排期</button></EditorPanel></template>
<template v-else-if="active==='navigation'"><text class="hint">为当前端的主题设置首页分类与底部导航。保存草稿并发布后，客户端同步生效。</text>
<EditorPanel v-for="group in [{name:'首页分类',key:'categories',isCategory:true},{name:'底部导航 / 脚页',key:'navigation',isCategory:false}]" :key="group.key" :auto-open="selected===group.key?selected:''" :title="group.name"><template #actions><view class="item-head"><button @click="addNav(theme[group.key as 'categories'|'navigation'],group.isCategory)">＋ 添加</button></view></template><EditorPanel v-for="n in theme[group.key as 'categories'|'navigation']" :key="n.id" :title="n.label"><template #actions><view class="item-head"><text @click="move(theme[group.key as 'categories'|'navigation'],n,-1)">↑</text><text @click="move(theme[group.key as 'categories'|'navigation'],n,1)">↓</text><text @click="remove(theme[group.key as 'categories'|'navigation'],n)">移除</text></view></template><view class="toggle"><text>显示入口</text><switch :checked="n.enabled" @change="n.enabled=bool($event)"/></view><label>显示名字<input v-model="n.label" maxlength="20"/></label><label>点击页面<Choice v-model="n.page" :options="pages"/></label><label>绑定目录分类<CmsCategoryBinding :model-value="n.categoryId" :categories="props.categories" @update:model-value="bindNavCategory(n,$event)"/></label><template v-if="!group.isCategory"><label>未选中图标<input v-model="n.icon" placeholder="符号或图片地址"/></label><button :disabled="uploading" @click="upload(n,'icon')">上传未选中图标</button><label>选中图标<input v-model="n.activeIcon"/></label><button :disabled="uploading" @click="upload(n,'activeIcon')">上传选中图标</button></template></EditorPanel><text class="hint">入口名字独立于 CMS 原分类名称。分类绑定按真实 ID 读取内容。</text></EditorPanel>
</template>
<template v-else-if="active==='features'"><EditorPanel  title="功能开关"><view class="toggle" v-for="f in [{id:'serviceMenu',name:'左上角三条杠菜单'},{id:'member',name:'独立会员页面'},{id:'memberCard',name:'我的会员卡'},{id:'shortdrama',name:'短剧'},{id:'schedule',name:'独立排期表页面'},{id:'ranking',name:'独立排行榜页面'}]" :key="f.id"><text>{{f.name}}</text><switch :checked="theme.features[f.id as keyof Theme['features']]" @change="setFeatureEnabled(theme,f.id as keyof Theme['features'],bool($event))" color="#73b79a"/></view><text class="hint">三条杠菜单控制手机左上角入口，关闭时同时收起菜单。排期表和排行榜分别控制；开启时添加独立底部入口。关闭后相应页面入口、分类和底部导航一起隐藏，原配置保留。</text></EditorPanel><text class="hint">这里管理业务功能是否开放。页面模块、导航与内容排序在“页面编排”管理；会员与收费管理套餐对接。</text></template>
<template v-else-if="active==='visual'"><EditorPanel title="骨架的界面样式" :initial-open="true"><text class="hint">为当前骨架设置页头、会员页、我的页和导航外观。运营人员在页面编排中选择轮播及模块样式、绑定内容和调整顺序。</text></EditorPanel><EditorPanel title="截图排版预设" :initial-open="true"><label>整体骨架<Choice v-model="theme.pageStyles.design" :options="[{id:'youku',label:'参考截图排版'},{id:'classic',label:'经典排版'}]"/></label><button @click="applyReferenceLayout(theme);emit('message','已应用截图排版到当前草稿，可继续调整；保存发布后客户端生效。')">应用截图排版</button><text class="hint">调整黑色配色、通栏轮播、小圆角海报及文字导航。品牌、目录绑定和功能开关保留。</text></EditorPanel><EditorPanel  title="固定界面样式"><label>页头<Choice v-model="theme.pageStyles.header" :options="[{id:'search',label:'搜索为主'},{id:'brand',label:'品牌与搜索'}]"/></label><label>会员页面<Choice v-model="theme.pageStyles.member" :options="[{id:'violet',label:'紫金会员卡'},{id:'gold',label:'黑金会员卡'}]"/></label><label>我的页面<Choice v-model="theme.pageStyles.mine" :options="[{id:'card',label:'卡片式'},{id:'minimal',label:'简约式'}]"/></label><label>底部导航<Choice v-model="theme.pageStyles.navigation" :options="[{id:'icons',label:'图标与文字'},{id:'text',label:'文字导航'}]"/></label></EditorPanel><EditorPanel title="卡片默认样式"><label>默认海报圆角 px<input v-model.number="theme.layout.posterRadius" type="number"/></label><text class="hint">未单独设置圆角的影片模块使用此默认值；模块专属设置优先。</text></EditorPanel></template>
<template v-else-if="active==='decoration'"><EditorPanel  title="主题配色"><label v-for="c in [{id:'accent',label:'品牌强调色'},{id:'background',label:'页面背景'},{id:'surface',label:'卡片背景'},{id:'text',label:'主要文字'},{id:'muted',label:'次要文字'}]" :key="c.id">{{c.label}}<view class="color-row"><view :style="{background:theme.colors[c.id as keyof Theme['colors']]}"/><input v-model="theme.colors[c.id as keyof Theme['colors']]" maxlength="7"/></view></label><view class="color-presets"><button @click="theme.colors={background:'#101014',surface:'#1c1c24',text:'#f4f4f8',muted:'#9999aa',accent:'#35d4ec'}">☾ 黑色</button><button @click="theme.colors={background:'#ffffff',surface:'#f2f4f6',text:'#15181c',muted:'#65707c',accent:'#087f98'}">☀ 白色</button><text @click="theme.colors={background:'#101014',surface:'#1c1c24',text:'#f4f4f8',muted:'#9999aa',accent:'#35d4ec'}">光影青</text><text @click="theme.colors={background:'#121019',surface:'#211c2e',text:'#f6f2ff',muted:'#a69bb8',accent:'#b8a2fa'}">午夜紫</text><text @click="theme.colors={background:'#f5f1e9',surface:'#e8e2d6',text:'#272b26',muted:'#7c8074',accent:'#9c6438'}">暖白</text></view></EditorPanel><EditorPanel  title="节日装饰"><view class="toggle"><text>开启装饰</text><switch :checked="theme.festival.enabled" @change="theme.festival.enabled=bool($event)"/></view><Choice v-model="theme.festival.kind" :options="[{id:'none',label:'日常'},{id:'spring',label:'春节'},{id:'midautumn',label:'中秋'},{id:'christmas',label:'圣诞'}]"/></EditorPanel></template>
<template v-else-if="active==='notice'"><EditorPanel title="公告展示" :initial-open="true"><view class="toggle"><text>显示公告</text><switch :checked="theme.announcement.enabled" @change="theme.announcement.enabled=bool($event)"/></view><label>展示方式<Choice v-model="theme.announcement.style" :options="[{id:'strip',label:'横条公告'},{id:'ticker',label:'滚动公告'},{id:'card',label:'图文卡片'},{id:'modal',label:'弹窗公告'}]"/></label><label>公告标题<input v-model="theme.announcement.title" maxlength="60"/></label><label>公告正文<textarea v-model="theme.announcement.text" maxlength="4000"/></label><label>公告图片<input v-model="theme.announcement.image" placeholder="图片地址，或上传图片"/></label><button :disabled="uploading" @click="upload(theme.announcement,'image')">上传公告图片</button><label>弹窗频次<Choice v-model="theme.announcement.frequency" :options="[{id:'launch',label:'每次启动'},{id:'daily',label:'每天一次'},{id:'once',label:'此公告只展示一次'}]"/></label><label>按钮文字<input v-model="theme.announcement.actionLabel" maxlength="20"/></label><label>点击跳转页面<Choice v-model="theme.announcement.page" :options="pages"/></label><label>外部链接（优先）<input v-model="theme.announcement.url" placeholder="https://…"/></label><button @click="emit('page','home');theme.announcement.style==='modal'&&emit('announcement')">预览当前公告</button><text class="hint">弹窗在启动页和开屏广告之后展示；版本更新优先。工作台预览不消耗用户展示次数。</text></EditorPanel></template>
<template v-else-if="active==='ads'"><EditorPanel  title="广告中心"><template #actions><view class="item-head"><button @click="addAd">＋ 添加广告</button></view></template><text class="hint">开机、首页、详情、播放器、短剧、我的页面分别配置。图片和视频保存于外部素材目录。</text><EditorPanel v-for="a in theme.ads" :key="a.id" :title="a.name"><template #actions><view class="item-head"><text @click="move(theme.ads,a,-1)">↑</text><text @click="move(theme.ads,a,1)">↓</text><text @click="remove(theme.ads,a)">移除</text></view></template><view class="toggle"><text>投放开关</text><switch :checked="a.enabled" @change="a.enabled=bool($event)"/></view><label>广告名称<input v-model="a.name"/></label><label>广告位<Choice v-model="a.slot" :options="[{id:'startup',label:'开屏广告'},{id:'home',label:'首页信息流'},{id:'detail',label:'影片详情'},{id:'player',label:'播放页'},{id:'shortdrama',label:'短剧页'},{id:'mine',label:'我的页面横幅'}]"/></label><label>素材类型<Choice v-model="a.media" :options="[{id:'image',label:'图片'},{id:'video',label:'视频'}]"/></label><label>素材地址<input v-model="a.asset"/></label><button :disabled="uploading" @click="upload(a,'asset',a.media==='video'?'.mp4':'.png,.jpg,.jpeg,.webp')">上传广告素材</button><label>点击外部地址<input v-model="a.url" placeholder="https://…，留空跳转内部页面"/></label><Choice v-model="a.page" :options="pages"/><label>开始时间<input v-model="a.start" placeholder="留空立即，例2026-10-10T08:00:00+08:00"/></label><label>结束时间<input v-model="a.end" placeholder="留空长期投放"/></label><view class="row"><label>开屏展示秒<input v-model.number="a.duration" type="number"/></label><label>允许跳过秒<input v-model.number="a.skipAfter" type="number"/></label></view><label>展示频率<Choice v-model="a.frequency" :options="[{id:'session',label:'每次启动一次'},{id:'always',label:'每次进入展示'}]"/></label></EditorPanel><text class="hint" v-if="!theme.ads.length">暂无广告，添加素材并开启后，在浏览预览中查看相应位置。</text></EditorPanel></template>
<template v-else-if="active==='member'"><EditorPanel title="会员中心" :summary="theme.features.member?'已开启 · 显示会员页面与入口':'已关闭 · 隐藏会员页面与入口'" :initial-open="true"><view class="toggle"><text>开启独立会员页面</text><switch :checked="theme.features.member" @change="theme.features.member=bool($event)" color="#73b79a"/></view><text class="hint">此开关只控制独立会员页面和对应导航。我的会员卡独立控制，账号登录始终保留。</text></EditorPanel><EditorPanel title="我的会员卡" :initial-open="true"><view class="toggle"><text>显示我的会员卡</text><switch :checked="theme.features.memberCard" @change="theme.features.memberCard=bool($event)" color="#73b79a"/></view><text class="hint">控制我的页面中的会员卡和权益入口，独立会员页关闭时仍可使用。关闭卡片后保留账号登录。</text><button @click="emit('page','mine')">打开我的页面预览</button></EditorPanel><EditorPanel title="CMS 会员与收费"><text class="hint">使用苹果 CMS 原账号、会员组、积分、到期时间与订单。当前模板只控制会员页面样式，实际套餐和支付渠道在 CMS 后台设置。</text><label>会员界面风格<Choice v-model="theme.pageStyles.member" :options="[{id:'violet',label:'紫金会员卡'},{id:'gold',label:'黑金会员卡'}]"/></label><button :disabled="!theme.features.member" @click="emit('page','member')">{{theme.features.member?'打开会员页面预览':'会员中心已关闭'}}</button><text class="hint">收费及播放权限适配文件：server/maccms-extension/Hetun.php。实际站点未连接时不模拟付款成功。iOS 内购等待 Apple 商品和服务端验证配置。</text></EditorPanel></template>
</view></template>
<style scoped>.theme-editor{color:var(--studio-text,#d8e3df);font-size:12px}.editor-panel{padding:20px;border:1px solid var(--studio-border,#ffffff12);border-radius:12px;background:var(--studio-panel,#111b21);margin-bottom:16px}.heading{font-size:15px;font-weight:600;display:block;margin-bottom:15px}.editor-panel label{display:flex;flex-direction:column;gap:8px;color:var(--studio-muted,#a2b4b1);margin:16px 0;font-size:11px}.editor-panel input{height:39px;background:var(--studio-input,#172329);border:1px solid var(--studio-border,#ffffff12);border-radius:6px;padding:0 12px;color:var(--studio-text,#d8e3df);min-width:0;box-sizing:border-box;font-size:12px;width:100%}.row{display:flex;gap:10px}.row label{flex:1;min-width:0}.toggle{display:flex;align-items:center;justify-content:space-between;margin:14px 0;gap:10px}.hint{display:block;font-size:11px;color:var(--studio-muted,#7f9693);line-height:1.9;margin:14px 0}.editor-panel button{border:1px solid var(--studio-border,#ffffff12);background:var(--studio-action,#21342e);color:var(--studio-muted,#cce6ce);padding:8px 12px;font-size:11px;border-radius:6px;line-height:1.8;cursor:pointer}.item{padding:14px;background:#ffffff03;border:1px solid var(--studio-border,#ffffff12);border-radius:8px;margin:15px 0}.item-head{display:flex;align-items:center;gap:12px}.item-head>text:first-child{flex:1}.item-head>text:not(:first-child){cursor:pointer;color:var(--studio-muted,#9cbbb1);font-size:11px}.item-head .heading{margin:0}.module-row{display:flex;gap:12px;padding:12px;border:1px solid var(--studio-border,#ffffff12);margin:8px 0;border-radius:6px;cursor:pointer}.module-row>text:first-child{flex:1}.selected{border-color:var(--studio-link,#8caf73);background:#8caf730d}.color-row{display:flex;gap:12px;align-items:center}.color-row>view{height:25px;width:25px;border-radius:50%;border:1px solid #ffffff30;flex-shrink:0}.color-presets{flex-wrap:wrap;display:flex;gap:18px;color:var(--studio-muted,#adccae)}.color-presets>text{cursor:pointer}.editor-panel textarea{width:100%;height:110px;padding:12px;box-sizing:border-box;background:var(--studio-input,#172329);border:1px solid var(--studio-border,#ffffff12);border-radius:7px;color:var(--studio-text,#d8e3df)}.asset-preview{height:70px;width:100%;margin:10px 0}</style>